## Submitted testbench
```systemverilog
module tb;

  // ------------------------------------------------------------
  //  Parameters
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8; // 125 MHz

  // ------------------------------------------------------------
  //  Clock generation
  // ------------------------------------------------------------
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  //  Reset
  // ------------------------------------------------------------
  logic rst = 0;

  // ------------------------------------------------------------
  //  DUT signal declarations
  // ------------------------------------------------------------
  logic [7:0] s_axis_tdata;
  logic       s_axis_tvalid;
  logic       s_axis_tready;   // output of DUT
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       m_axis_tready;   // input to DUT (tied to 1)

  logic txd;
  logic tx_busy;
  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;
  logic [15:0] prescale_val;

  // Drive rxd
  reg rxd_drv;

  // ------------------------------------------------------------
  //  DUT instantiation
  // ------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),

    // AXI input
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),

    // AXI output
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),

    // UART interface
    .rxd          (rxd_drv),
    .txd          (txd),

    // Status
    .tx_busy      (tx_busy),
    .rx_busy      (rx_busy),
    .rx_overrun_error (rx_overrun_error),
    .rx_frame_error   (rx_frame_error),

    // Configuration
    .prescale     (prescale_val)
  );

  // ------------------------------------------------------------
  //  Tie off unused or unneeded signals
  // ------------------------------------------------------------
  assign m_axis_tready = 1'b1;                // always ready
  assign s_axis_tdata  = 8'h00;               // idle data
  assign s_axis_tvalid = 1'b0;                // never drive TACVALID

  // ------------------------------------------------------------
  //  Reset task
  // ------------------------------------------------------------
  task automatic do_reset();
    rst = 0;
    repeat (2) @(posedge clk);
    rst = 1;
    repeat (2) @(posedge clk);
    rst = 0;
    repeat (2) @(posedge clk);
  endtask

  // ------------------------------------------------------------
  //  Frame transmission task (LSB‑first)
  // ------------------------------------------------------------
  task automatic send_frame(input byte unsigned data_byte);
    int bc;
    bc = prescale_val * 8;

    // Start bit (low)
    rxd_drv = 1'b0;
    for (int i = 0; i < bc; i = i + 1) @(posedge clk);

    // Data bits, LSB first
    for (int i = 0; i < 8; i = i + 1) begin
      rxd_drv = data_byte[i];
      for (int j = 0; j < bc; j = j + 1) @(posedge clk);
    end

    // Stop bit (high)
    rxd_drv = 1'b1;
    for (int k = 0; k < bc; k = k + 1) @(posedge clk);
  endtask

  // ------------------------------------------------------------
  //  Main stimulus
  // ------------------------------------------------------------
  initial begin
    // Initialise configuration
    prescale_val = 16'd1;

    // Reset the DUT
    do_reset();

    // ------------------------------------------------------------
    // 1) Send 0xA5 while prescale = 1
    // ------------------------------------------------------------
    repeat (4) @(posedge clk);               // small idle after reset
    send_frame(8'hA5);                        // first frame

    // Wait until the receiver is idle (busy goes low)
    repeat (150) @(posedge clk);

    // Change prescale to 2 while busy is low (allowed)
    prescale_val = 16'd2;
    repeat (5) @(posedge clk);               // small idle

    // ------------------------------------------------------------
    // 2) Send 0x5A while prescale = 2
    // ------------------------------------------------------------
    send_frame(8'h5A);                        // second frame

    // Give the design time to present m_axis_tvalid/frame_error
    repeat (200) @(posedge clk);

    $display("Simulation completed");
    $finish;
  end

endmodule
```

